import {divisionStages,divisionState,breathingModel} from './division-science.js';
import {markActivity} from './journey-data.js';
export function createBioLab(root,api){
 let selected='stations',active=false,scope=null,mode='mitosis',phase=0,timer=null,model=null,modelLoading=null,breath=0,breathFrame=0,last=0;
 root.innerHTML=`<header class="campus-heading biolab-heading"><div><span class="eyebrow">BIOLAB / PHÒNG THÍ NGHIỆM SINH HỌC ẢO</span><h1 data-page-heading tabindex="-1">Đặt một giả thuyết.<br><em>Nhìn sự sống chuyển động.</em></h1><p>Một phòng lab chung cho thí nghiệm, kính hiển vi, phân bào và sinh lý. Chọn công cụ, thay điều kiện rồi giữ lại bằng chứng.</p></div><a class="campus-link" href="#/notebook">Sổ tay thí nghiệm ↗</a></header><div class="biolab-workbench"><aside class="biolab-tools" aria-label="Chọn bàn thí nghiệm"><span class="campus-kicker">BÀN NGHIÊN CỨU</span><button type="button" data-biolab-tab="stations"><span>⚗</span><b>Trạm thí nghiệm</b><small>Plant · Genetics · Enzyme · Ecology</small></button><button type="button" data-biolab-tab="microscope"><span>◉</span><b>Cell Lab</b><small>Kính hiển vi · 5 tiêu bản</small></button><button type="button" data-biolab-tab="division"><span>⊙</span><b>Phân bào 3D</b><small>Nguyên phân & giảm phân</small></button><button type="button" data-biolab-tab="human"><span>⌁</span><b>Human Lab</b><small>Cơ học của một nhịp thở</small></button><p>Quan sát → Dự đoán → Thử → Giải thích</p></aside><div class="biolab-main"><section id="biolab-panel-stations" class="biolab-panel"><div class="biolab-welcome"><div><span class="campus-kicker">MỖI THAO TÁC MỘT CÂU HỎI</span><h2>Bàn thí nghiệm đang mở.</h2><p>Quang hợp, thẩm thấu, enzyme, hướng sáng, lai Mendel và dòng năng lượng. Mỗi trạm có điều kiện điều chỉnh và nhật ký so sánh.</p></div><div class="biolab-glassware" aria-hidden="true"><i></i><i></i><i></i><span>VNS / LAB 01</span></div></div><div class="lab-page-toolbar"><div class="catalog-tabs" role="group" aria-label="Lọc thí nghiệm theo lớp"><button data-lab-grade="all" class="selected" aria-pressed="true">Tất cả</button><button data-lab-grade="10" aria-pressed="false">Lớp 10</button><button data-lab-grade="11" aria-pressed="false">Lớp 11</button><button data-lab-grade="12" aria-pressed="false">Lớp 12</button></div><span id="lab-catalog-count"></span></div><div id="lab-catalog" class="lab-catalog"></div></section><section id="biolab-panel-microscope" class="biolab-panel" hidden><div class="biolab-panel-title"><span class="campus-kicker">CELL LAB / QUAN SÁT VI MÔ</span><h2>Một thế giới qua thị kính.</h2><p>Tiêu bản thực vật, nguyên sinh vật và máu. Tự đổi vật kính, tìm nét và ghi nhận cấu trúc; đồ họa là minh họa có nguồn.</p></div><div id="microscope-app"></div></section><section id="biolab-panel-division" class="biolab-panel" hidden><div class="biolab-panel-title"><span class="campus-kicker">CELL LAB / CHU KÌ TẾ BÀO</span><h2>Một lần sao chép. Những cách phân chia.</h2><p>Theo dõi mô hình tế bào 2n = 4. Phân biệt nhiễm sắc thể tương đồng với chromatid chị em.</p></div><div class="division-controls"><label for="division-mode">Quá trình <select id="division-mode"><option value="mitosis">Chu kì tế bào & nguyên phân</option><option value="meiosis">Giảm phân</option></select></label><button type="button" id="division-play" class="campus-button secondary" aria-pressed="false">Chạy từng giai đoạn ▷</button></div><label class="campus-label" for="division-prediction">Dự đoán trước khi chạy</label><textarea id="division-prediction" rows="2" maxlength="1200" placeholder="Kết thúc quá trình, số tế bào và số NST ở mỗi tế bào thay đổi thế nào?"></textarea><div class="division-layout"><div class="division-viewport"><div id="division-model" role="group" aria-label="Mô hình phân bào ba chiều"></div><span>Kéo để đổi góc nhìn · Hình và màu quy ước</span></div><aside><span class="campus-kicker" id="division-stage-count"></span><h3 id="division-stage-name"></h3><p id="division-stage-text"></p><div class="division-metrics"><span id="division-cell-count"></span><span id="division-nst-count"></span></div></aside></div><label for="division-phase" class="campus-label">Đi tới giai đoạn</label><input id="division-phase" type="range" min="0" max="5" value="0" step="1"><div id="division-stops" class="division-stops"></div><button type="button" id="division-save" class="campus-button">Lưu báo cáo phân bào</button><details class="campus-source"><summary>Cơ sở học liệu & giới hạn</summary><p>Đối chiếu chủ đề chu kì tế bào, nguyên phân và giảm phân trong SGK Sinh học 10 NXBGDVN. Mô hình chỉ có 2n = 4 để dễ đếm, lược bỏ nhiều cấu trúc và không mô phỏng đầy đủ trao đổi chéo hoặc cơ chế phân li. G₁, S, G₂ thuộc kì trung gian, không gọi là các kì của nguyên phân.</p><a href="https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/sach.4492290247.4492290247" target="_blank" rel="noopener">SGK Sinh học 10 · NXBGDVN ↗</a><a href="https://openstax.org/books/biology-2e/pages/11-1-the-process-of-meiosis" target="_blank" rel="noopener">OpenStax · Meiosis ↗</a></details></section><section id="biolab-panel-human" class="biolab-panel" hidden><div class="biolab-panel-title"><span class="campus-kicker">HUMAN LAB / SINH LÝ CƠ THỂ</span><h2>Không khí đi vào bằng cách nào?</h2><p>Quan sát sự phối hợp cơ hoành, thể tích lồng ngực và chuyển động không khí khi thở yên tĩnh.</p></div><div class="breathing-layout"><div id="breathing-scene" class="breathing-scene"></div><aside><span class="campus-kicker">QUAN SÁT TỪNG NHỊP</span><h3 id="breathing-label"></h3><p id="breathing-explanation"></p><label for="breathing-phase">Tiến trình một chu kì <input id="breathing-phase" type="range" min="0" max="99" value="15"></label><button id="breathing-play" type="button" class="campus-button" aria-pressed="false">Chạy nhịp thở ▷</button><button id="breathing-save" type="button" class="campus-button secondary">Ghi một quan sát</button></aside></div><details class="campus-source"><summary>Học liệu & giới hạn mô hình</summary><p>Chủ đề hô hấp ở người, KHTN8 NXBGDVN. Chuyển động và đồ thị là định tính, không đo dung tích phổi, nhịp thở hoặc tình trạng sức khỏe của người xem.</p><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing" target="_blank" rel="noopener">OpenStax · Cơ học thông khí ↗</a></details></section></div></div>`;
 function stopDivision(){clearInterval(timer);timer=null;root.querySelector('#division-play').setAttribute('aria-pressed','false');root.querySelector('#division-play').textContent='Chạy từng giai đoạn ▷'}
 function drawDivision(){const s=divisionState(mode,phase),list=divisionStages[mode];root.querySelector('#division-stage-count').textContent=`${phase+1} / ${list.length} GIAI ĐOẠN`;root.querySelector('#division-stage-name').textContent=s.name;root.querySelector('#division-stage-text').textContent=s.text;root.querySelector('#division-cell-count').textContent=`${s.cells} tế bào trong mô hình`;root.querySelector('#division-nst-count').textContent=`${s.nst} NST / tế bào đang xét`;root.querySelector('#division-phase').max=list.length-1;root.querySelector('#division-phase').value=phase;root.querySelector('#division-stops').innerHTML=list.map((d,i)=>`<button type="button" data-division-stage="${i}" aria-pressed="${i===phase}">${i+1}<span>${d.name}</span></button>`).join('');model?.draw(mode,phase)}
 async function ensureModel(){if(model){model.resize();return}if(modelLoading)return modelLoading;const host=root.querySelector('#division-model');host.innerHTML='<div class="cell-loading" role="status">Đang mở mô hình tế bào…</div>';modelLoading=import('./division-model.js').then(({createDivisionModel})=>{host.replaceChildren();model=createDivisionModel(host);drawDivision()}).catch(()=>{host.innerHTML='<p class="campus-small">Mô hình 3D chưa tải được. Bạn vẫn có thể chọn giai đoạn và đọc chú giải bên cạnh.</p>'});return modelLoading}
 function drawBreathing(){const m=breathingModel(breath),v=.82+m.expansion*.18;root.querySelector('#breathing-label').textContent=m.label;root.querySelector('#breathing-explanation').textContent=m.text;root.querySelector('#breathing-phase').value=Math.floor(breath);root.querySelector('#breathing-scene').innerHTML=`<svg viewBox="0 0 620 410" role="img" aria-label="Cơ hoành và phổi trong ${m.label.toLowerCase()}"><path d="M225 45q-70 25-80 120v145q165 55 330 0V165q-10-95-80-120" fill="#dbe7ca" stroke="#8ca88c" stroke-width="3"/><path d="M310 28v130m0-30-65 55m65-55 65 55" fill="none" stroke="#a29d80" stroke-width="17" stroke-linecap="round"/><g transform="translate(310 220) scale(${v})"><path d="M-22-79q-100-67-128 64-16 85 73 69 49-8 55-40Z" fill="#a6c6b4" stroke="#6c9c84" stroke-width="2"/><path d="M22-79q100-67 128 64 16 85-73 69-49-8-55-40Z" fill="#a6c6b4" stroke="#6c9c84" stroke-width="2"/></g><path d="M157 ${307+m.expansion*17}q153 ${-70+m.expansion*57} 306 0" stroke="#b8a376" stroke-width="9" fill="none"/><path class="breathing-air ${m.inhale?'in':'out'}" d="M310 40v85" stroke="#699c9b" stroke-width="6" stroke-dasharray="6 14"/><text x="310" y="385" text-anchor="middle" fill="#456347" font-size="16">Cơ hoành ${m.inhale?'co và hạ xuống':'giãn, vòm nâng lên'}</text></svg>`}
 function breathe(now){if(!active||selected!=='human'){cancelAnimationFrame(breathFrame);breathFrame=0;return}breath=(breath+Math.min(70,now-last||16)/70)%100;last=now;drawBreathing();breathFrame=requestAnimationFrame(breathe)}
 function stopBreathing(){cancelAnimationFrame(breathFrame);breathFrame=0;last=0;root.querySelector('#breathing-play').setAttribute('aria-pressed','false');root.querySelector('#breathing-play').textContent='Chạy nhịp thở ▷'}
 function select(tab){selected=['stations','microscope','division','human'].includes(tab)?tab:'stations';root.querySelectorAll('[data-biolab-tab]').forEach(b=>{const yes=b.dataset.biolabTab===selected;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))});root.querySelectorAll('.biolab-panel').forEach(p=>p.hidden=p.id!=='biolab-panel-'+selected);scope?.setActive(active&&selected==='microscope');if(selected==='division')ensureModel();else{stopDivision();model?.setActive?.(false)}if(selected!=='human')stopBreathing();else drawBreathing()}
 root.querySelectorAll('[data-biolab-tab]').forEach(b=>b.addEventListener('click',()=>api.navigate('lab/'+b.dataset.biolabTab)));root.querySelector('#division-mode').addEventListener('change',e=>{mode=e.target.value;phase=0;stopDivision();drawDivision()});root.querySelector('#division-phase').addEventListener('input',e=>{phase=Number(e.target.value);stopDivision();drawDivision()});root.addEventListener('click',e=>{const b=e.target.closest('[data-division-stage]');if(b){phase=Number(b.dataset.divisionStage);stopDivision();drawDivision()}});
 root.querySelector('#division-play').addEventListener('click',()=>{if(timer){stopDivision();return}if(phase===divisionStages[mode].length-1)phase=0;timer=setInterval(()=>{if(!active||document.hidden){stopDivision();return}phase++;drawDivision();if(phase>=divisionStages[mode].length-1)stopDivision()},2400);root.querySelector('#division-play').textContent='Tạm dừng Ⅱ';root.querySelector('#division-play').setAttribute('aria-pressed','true')});
 root.querySelector('#division-save').addEventListener('click',()=>{const s=api.getState();markActivity(s);api.addNote(`BioLab: ${mode==='mitosis'?'Nguyên phân':'Giảm phân'}`,`Dự đoán của tôi: ${root.querySelector('#division-prediction').value.trim()||'Chưa ghi'}\n\nGiai đoạn: ${divisionState(mode,phase).name}\n${divisionState(mode,phase).text}\n\nMô hình 2n = 4, màu quy ước; không phải ảnh quan sát thực.\nNguồn SGK Sinh học 10: https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/sach.4492290247.4492290247`);api.toast('Đã giữ báo cáo phân bào trong sổ tay.')});root.querySelector('#breathing-phase').addEventListener('input',e=>{stopBreathing();breath=Number(e.target.value);drawBreathing()});root.querySelector('#breathing-play').addEventListener('click',()=>{if(breathFrame){stopBreathing();return}root.querySelector('#breathing-play').textContent='Tạm dừng Ⅱ';root.querySelector('#breathing-play').setAttribute('aria-pressed','true');breathFrame=requestAnimationFrame(breathe)});root.querySelector('#breathing-save').addEventListener('click',()=>{markActivity(api.getState());api.addNote('BioLab: Một nhịp thở',`${breathingModel(breath).label}\n${breathingModel(breath).text}\n\nĐiều tôi muốn giải thích thêm:\n\nSơ đồ định tính, không phải phép đo sinh lý.\nNguồn: https://openstax.org/books/anatomy-and-physiology-2e/pages/22-3-the-process-of-breathing`);api.toast('Đã lưu một điểm quan sát sinh lý.')});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopDivision();stopBreathing()}});select('stations');drawDivision();drawBreathing();return {select,setMicroscope(value){scope=value},get selected(){return selected},setActive(value){active=value;scope?.setActive(value&&selected==='microscope');if(!value){stopDivision();stopBreathing();model?.setActive?.(false)}else if(selected==='division')ensureModel()}};
}
